async function loadTeamState(context) {
	const { supabase, userId } = context;
	const { data: ownTeam } = await supabase.from("teams").select("id, name, owner_id").eq("owner_id", userId).maybeSingle();
	let team = ownTeam ?? null;
	let myRole = ownTeam ? "moderator" : null;
	if (!team) {
		const { data: membership } = await supabase.from("team_members").select("role, teams(id, name, owner_id)").eq("user_id", userId).maybeSingle();
		if (membership?.teams) {
			team = membership.teams;
			myRole = membership.role;
		}
	}
	const email = ctxEmail(context);
	const pendingForMe = [];
	if (email) try {
		const { supabaseAdmin } = await import("./client.server-CNVO71Jz.js");
		const { data: invites } = await supabaseAdmin.from("team_invitations").select("token, role, status, expires_at, teams(name)").eq("email", email).eq("status", "pending");
		(invites ?? []).forEach((i) => {
			if (new Date(i.expires_at).getTime() < Date.now()) return;
			pendingForMe.push({
				token: i.token,
				teamName: i.teams?.name ?? "",
				role: i.role
			});
		});
	} catch {}
	if (!team) return {
		...EMPTY_TEAM_STATE,
		pendingForMe
	};
	const isOwner = team.owner_id === userId;
	const canManage = isOwner || myRole === "moderator";
	const { data: memberRows } = await supabase.from("team_members").select("id, user_id, role, created_at").eq("team_id", team.id).order("created_at", { ascending: true });
	const emails = await emailsFor([team.owner_id, ...(memberRows ?? []).map((m) => m.user_id)]);
	const members = [{
		id: `owner-${team.owner_id}`,
		user_id: team.owner_id,
		email: emails.get(team.owner_id) || `${team.owner_id.slice(0, 8)}…`,
		role: "moderator",
		isOwner: true,
		created_at: ""
	}, ...(memberRows ?? []).map((m) => ({
		id: m.id,
		user_id: m.user_id,
		email: emails.get(m.user_id) || `${String(m.user_id).slice(0, 8)}…`,
		role: m.role,
		isOwner: false,
		created_at: m.created_at
	}))];
	let invitations = [];
	if (canManage) {
		const { data: inv } = await supabase.from("team_invitations").select("id, email, role, token, status, expires_at, created_at").eq("team_id", team.id).eq("status", "pending").order("created_at", { ascending: false });
		invitations = inv ?? [];
	}
	return {
		team,
		myRole,
		isOwner,
		canManage,
		members,
		invitations,
		pendingForMe
	};
}
async function acceptInvitationFor(context, token) {
	const email = ctxEmail(context);
	if (!email) throw new Error("NO_EMAIL");
	const { supabaseAdmin } = await import("./client.server-CNVO71Jz.js");
	const { data: invite } = await supabaseAdmin.from("team_invitations").select("id, team_id, email, role, status, expires_at").eq("token", token).maybeSingle();
	if (!invite || invite.status !== "pending") throw new Error("INVALID_INVITE");
	if (String(invite.email).toLowerCase() !== email) throw new Error("WRONG_ACCOUNT");
	if (new Date(invite.expires_at).getTime() < Date.now()) throw new Error("EXPIRED");
	const { error } = await supabaseAdmin.from("team_members").upsert({
		team_id: invite.team_id,
		user_id: context.userId,
		role: invite.role
	}, { onConflict: "team_id,user_id" });
	if (error) throw new Error(error.message);
	await supabaseAdmin.from("team_invitations").update({ status: "accepted" }).eq("id", invite.id);
	return { ok: true };
}
